class TestHostMatching(_Routing):
    @classmethod
    def setup_class(cls) -> None:
        cls.url_map = r.Map(
            [
                r.Rule("/", host="app.test", endpoint="index"),
                r.Rule("/", host="<lang>.app.test", endpoint="lang"),
                r.Rule(
                    "/page/", host="app.<domain>", defaults={"page": 1}, endpoint="page"
                ),
                r.Rule("/page/<int:page>/", host="pages.<domain>", endpoint="page"),
            ],
            host_matching=True,
        )

    default_base_url = "http://app.test"
    default_server_name = None

    def test_match_host(self) -> None:
        assert self._match() == ("index", {})

    def test_no_match_other_host(self) -> None:
        with pytest.raises(NotFound):
            self._match(base_url="somewhere.test")

    def test_match_host_prefix(self) -> None:
        assert self._match(base_url="en.app.test") == ("lang", {"lang": "en"})

    def test_match_host_suffix(self) -> None:
        assert self._match("/page/", base_url="app.personal.test") == (
            "page",
            {"domain": "personal.test", "page": 1},
        )

    def test_disables_subdomain_matching(self) -> None:
        assert not self.url_map.subdomain_matching

    def test_match_redirect_trailing_slash(self) -> None:
        with pytest.raises(r.RequestRedirect) as excinfo:
            self._match("/page", base_url="app.other.test")

        assert excinfo.value.new_url == "http://app.other.test/page/"

    def test_match_redirect_other_host(self) -> None:
        with pytest.raises(r.RequestRedirect) as excinfo:
            self._match("/page/1/", base_url="pages.personal.test")

        assert excinfo.value.new_url == "http://app.personal.test/page/"

    def test_build_same_host(self) -> None:
        assert self._build("index", base_url="app.test") == "/"
        assert (
            self._build("page", base_url="app.personal.test", domain="personal.test")
            == "/page/"
        )

    def test_build_other_host(self) -> None:
        assert self._build("index", base_url="pages.other.test") == "http://app.test/"
        assert (
            self._build("page", base_url="app.test", domain="personal.test")
            == "http://app.personal.test/page/"
        )

def get_host(self, domain_part: str | None) -> str:
        """Figures out the full host name for the given domain part.  The
        domain part is a subdomain in case host matching is disabled or
        a full host name.
        """
        if self.map.host_matching:
            if domain_part is None:
                return self.server_name

            return domain_part

        if domain_part is None:
            subdomain = self.subdomain
        else:
            subdomain = domain_part

        if subdomain:
            return f"{subdomain}.{self.server_name}"
        else:
            return self.server_name

def update(self) -> None:
        """Called before matching and building to keep the compiled rules
        in the correct order after things changed.
        """
        if not self._remap:
            return

        with self._remap_lock:
            if not self._remap:
                return

            self._matcher.update()
            for rules in self._rules_by_endpoint.values():
                rules.sort(key=lambda x: x.build_compare_key())
            self._remap = False

def _match(
            state: State, parts: list[str], values: list[str]
        ) -> tuple[Rule, list[str]] | None:
            # This function is meant to be called recursively, and will attempt
            # to match the head part to the state's transitions.
            nonlocal have_match_for, websocket_mismatch

            # The base case is when all parts have been matched via
            # transitions. Hence if there is a rule with methods &
            # websocket that work return it and the dynamic values
            # extracted.
            if parts == []:
                for rule in state.rules:
                    if rule.methods is not None and method not in rule.methods:
                        have_match_for.update(rule.methods)
                    elif rule.websocket != websocket:
                        websocket_mismatch = True
                    else:
                        return rule, values

                # Test if there is a match with this path with a
                # trailing slash, if so raise an exception to report
                # that matching is possible with an additional slash
                if "" in state.static:
                    for rule in state.static[""].rules:
                        if websocket == rule.websocket and (
                            rule.methods is None or method in rule.methods
                        ):
                            if rule.strict_slashes:
                                raise SlashRequired()
                            else:
                                return rule, values
                return None

            part = parts[0]
            # To match this part try the static transitions first
            if part in state.static:
                rv = _match(state.static[part], parts[1:], values)
                if rv is not None:
                    return rv
            # No match via the static transitions, so try the dynamic
            # ones.
            for test_part, new_state in state.dynamic:
                target = part
                remaining = parts[1:]
                # A final part indicates a transition that always
                # consumes the remaining parts i.e. transitions to a
                # final state.
                if test_part.final:
                    target = "/".join(parts)
                    remaining = []
                match = re.compile(test_part.content).match(target)
                if match is not None:
                    if test_part.suffixed:
                        # If a part_isolating=False part has a slash suffix, remove the
                        # suffix from the match and check for the slash redirect next.
                        suffix = match.groups()[-1]
                        if suffix == "/":
                            remaining = [""]

                    converter_groups = sorted(
                        (
                            item
                            for item in match.groupdict().items()
                            if item[0].startswith("__werkzeug_")
                        ),
                        key=lambda item: int(item[0][11:]),
                    )
                    groups = [item[1] for item in converter_groups]
                    rv = _match(new_state, remaining, values + groups)
                    if rv is not None:
                        return rv

            # If there is no match and the only part left is a
            # trailing slash ("") consider rules that aren't
            # strict-slashes as these should match if there is a final
            # slash part.
            if parts == [""]:
                for rule in state.rules:
                    if rule.strict_slashes:
                        continue
                    if rule.methods is not None and method not in rule.methods:
                        have_match_for.update(rule.methods)
                    elif rule.websocket != websocket:
                        websocket_mismatch = True
                    else:
                        return rule, values

            return None

