def getlist(
        self, key: K, type: cabc.Callable[[V], T] | None = None
    ) -> list[V] | list[T]:
        """Return the list of items for a given key. If that key is not in the
        `MultiDict`, the return value will be an empty list.  Just like `get`,
        `getlist` accepts a `type` parameter.  All items will be converted
        with the callable defined there.

        :param key: The key to be looked up.
        :param type: Callable to convert each value. If a ``ValueError`` or
            ``TypeError`` is raised, the value is omitted.
        :return: a :class:`list` of all the values for the key.

        .. versionchanged:: 3.1
            Catches ``TypeError`` in addition to ``ValueError``.
        """
        try:
            rv: list[V] = super().__getitem__(key)  # type: ignore[assignment]
        except KeyError:
            return []
        if type is None:
            return list(rv)
        result = []
        for item in rv:
            try:
                result.append(type(item))
            except (ValueError, TypeError):
                pass
        return result

class CombinedMultiDict(ImmutableMultiDictMixin[K, V], MultiDict[K, V]):  # type: ignore[misc]
    """A read only :class:`MultiDict` that you can pass multiple :class:`MultiDict`
    instances as sequence and it will combine the return values of all wrapped
    dicts:

    >>> from werkzeug.datastructures import CombinedMultiDict, MultiDict
    >>> post = MultiDict([('foo', 'bar')])
    >>> get = MultiDict([('blub', 'blah')])
    >>> combined = CombinedMultiDict([get, post])
    >>> combined['foo']
    'bar'
    >>> combined['blub']
    'blah'

    This works for all read operations and will raise a `TypeError` for
    methods that usually change data which isn't possible.

    From Werkzeug 0.3 onwards, the `KeyError` raised by this class is also a
    subclass of the :exc:`~exceptions.BadRequest` HTTP exception and will
    render a page for a ``400 BAD REQUEST`` if caught in a catch-all for HTTP
    exceptions.
    """

    def __reduce_ex__(self, protocol: t.SupportsIndex) -> t.Any:
        return type(self), (self.dicts,)

    def __init__(self, dicts: cabc.Iterable[MultiDict[K, V]] | None = None) -> None:
        super().__init__()
        self.dicts: list[MultiDict[K, V]] = list(dicts or ())

    @classmethod
    def fromkeys(cls, keys: t.Any, value: t.Any = None) -> t.NoReturn:
        raise TypeError(f"cannot create {cls.__name__!r} instances by fromkeys")

    def __getitem__(self, key: K) -> V:
        for d in self.dicts:
            if key in d:
                return d[key]
        raise exceptions.BadRequestKeyError(key)

    @t.overload  # type: ignore[override]
    def get(self, key: K) -> V | None: ...
    @t.overload
    def get(self, key: K, default: V) -> V: ...
    @t.overload
    def get(self, key: K, default: T) -> V | T: ...
    @t.overload
    def get(self, key: str, type: cabc.Callable[[V], T]) -> T | None: ...
    @t.overload
    def get(self, key: str, default: T, type: cabc.Callable[[V], T]) -> T: ...
    def get(  # type: ignore[misc]
        self,
        key: K,
        default: V | T | None = None,
        type: cabc.Callable[[V], T] | None = None,
    ) -> V | T | None:
        for d in self.dicts:
            if key in d:
                if type is not None:
                    try:
                        return type(d[key])
                    except (ValueError, TypeError):
                        continue
                return d[key]
        return default

    @t.overload
    def getlist(self, key: K) -> list[V]: ...
    @t.overload
    def getlist(self, key: K, type: cabc.Callable[[V], T]) -> list[T]: ...
    def getlist(
        self, key: K, type: cabc.Callable[[V], T] | None = None
    ) -> list[V] | list[T]:
        rv = []
        for d in self.dicts:
            rv.extend(d.getlist(key, type))  # type: ignore[arg-type]
        return rv

    def _keys_impl(self) -> set[K]:
        """This function exists so __len__ can be implemented more efficiently,
        saving one list creation from an iterator.
        """
        return set(k for d in self.dicts for k in d)

    def keys(self) -> cabc.Iterable[K]:  # type: ignore[override]
        return self._keys_impl()

    def __iter__(self) -> cabc.Iterator[K]:
        return iter(self._keys_impl())

    @t.overload  # type: ignore[override]
    def items(self) -> cabc.Iterable[tuple[K, V]]: ...
    @t.overload
    def items(self, multi: t.Literal[True]) -> cabc.Iterable[tuple[K, list[V]]]: ...
    def items(
        self, multi: bool = False
    ) -> cabc.Iterable[tuple[K, V]] | cabc.Iterable[tuple[K, list[V]]]:
        found = set()
        for d in self.dicts:
            for key, value in d.items(multi):
                if multi:
                    yield key, value
                elif key not in found:
                    found.add(key)
                    yield key, value

    def values(self) -> cabc.Iterable[V]:  # type: ignore[override]
        for _, value in self.items():
            yield value

    def lists(self) -> cabc.Iterable[tuple[K, list[V]]]:
        rv: dict[K, list[V]] = {}
        for d in self.dicts:
            for key, values in d.lists():
                rv.setdefault(key, []).extend(values)
        return rv.items()

    def listvalues(self) -> cabc.Iterable[list[V]]:
        return (x[1] for x in self.lists())

    def copy(self) -> MultiDict[K, V]:  # type: ignore[override]
        """Return a shallow mutable copy of this object.

        This returns a :class:`MultiDict` representing the data at the
        time of copying. The copy will no longer reflect changes to the
        wrapped dicts.

        .. versionchanged:: 0.15
            Return a mutable :class:`MultiDict`.
        """
        return MultiDict(self)

    def __len__(self) -> int:
        return len(self._keys_impl())

    def __contains__(self, key: K) -> bool:  # type: ignore[override]
        for d in self.dicts:
            if key in d:
                return True
        return False

    def __repr__(self) -> str:
        return f"{type(self).__name__}({self.dicts!r})"

class Accept(cabc.Sequence[tuple[str, float]]):
    """A parsed ``Accept-Encoding`` header.

    Despite its name, this class is used for the ``Accept-Encoding`` header.
    :class:`.MIMEAccept` is used for the ``Accept`` header.

    .. versionchanged:: 3.2
        Inherits ``Sequence`` instead of ``ImmutableList``.

    .. versionchanged:: 1.0
        Items with equal quality preserve initial order instead of being ordered
        alphabetically.

    .. versionchanged:: 0.5
        Immutability is enforced.
    """

    def __init__(self, values: cabc.Iterable[tuple[str, float]] | None = None) -> None:
        if values is None:
            values = ()

        self._items = tuple(
            sorted(values, key=lambda x: (self._specificity(x[0]), x[1]), reverse=True)
        )

    def _specificity(self, value: str) -> tuple[bool, ...]:
        """Returns a tuple describing the value's specificity."""
        return (value != "*",)

    def _value_matches(self, app_value: str, req_value: str) -> bool:
        """Check if a value matches a specific value in the collection.

        :param app_value: The value to check.
        :param req_value: The value in the collection to check against.
        """
        return req_value == "*" or req_value.lower() == app_value.lower()

    @t.overload
    def __getitem__(self, key: str) -> float: ...
    @t.overload
    def __getitem__(self, key: t.SupportsIndex) -> tuple[str, float]: ...
    @t.overload
    def __getitem__(self, key: slice) -> tuple[tuple[str, float]]: ...
    def __getitem__(
        self, key: str | t.SupportsIndex | slice
    ) -> float | tuple[str, float] | tuple[tuple[str, float]]:
        """Get the quality for the given value, 0 if it is not in the
        collection. Or the entry at the given index, or a slice of entries.
        """
        if isinstance(key, str):
            return self.quality(key)

        return self._items[key]  # type: ignore[return-value]

    def quality(self, value: str) -> float:
        """Get the quality of the first value in the collection that matches the
        given value.

        :param value: The value to match.

        .. versionadded:: 0.6
        """
        for req_value, q in self:
            if self._value_matches(value, req_value):
                return q

        return 0

    def __contains__(self, value: str) -> bool:  # type: ignore[override]
        for req_value, _ in self:
            if self._value_matches(value, req_value):
                return True

        return False

    def __len__(self) -> int:
        return len(self._items)

    def __iter__(self) -> cabc.Iterator[tuple[str, float]]:
        return iter(self._items)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, self.__class__):
            return NotImplemented

        return self._items == other._items

    def __repr__(self) -> str:
        pairs_str = ", ".join(f"({value!r}, {q})" for value, q in self)
        return f"{type(self).__name__}([{pairs_str}])"

    def index(self, value: str | tuple[str, float]) -> int:  # type: ignore[override]
        """Return the index of the first value in the collection that matches
        the given value.

        :param value: A value to match, or a specific ``(value, quality)`` entry.
        :raises ValueError: If the key is not in the collection.

        .. versionchanged:: 0.5
            Raises ``ValueError`` instead of ``IndexError``.
        """
        if (rv := self.find(value)) == -1:
            raise ValueError(value)

        return rv

    def find(self, value: str | tuple[str, float]) -> int:
        """Return the index of the first value in the collection that matches
        the given value, or -1 if not found.

        :param value: A value to match, or a specific ``(value, quality)`` entry.
        """
        if isinstance(value, str):
            for idx, (req_value, _) in enumerate(self):
                if self._value_matches(value, req_value):
                    return idx

            return -1

        return self._items.index(value)

    def values(self) -> cabc.Iterator[str]:
        """Iterate over values, omitting the quality part."""
        for value, _ in self:
            yield value

    @classmethod
    def from_header(cls, value: str | None) -> te.Self:
        """Parse a header value and create an instance of this class.

        .. versionadded:: 3.2
        """
        if not value:
            return cls()

        result = []

        for item in parse_list_header(value):
            item, options = parse_options_header(item)

            if "q" in options:
                # pop q, remaining options are reconstructed
                q_str = options.pop("q").strip(" \t")

                if _q_value_re.fullmatch(q_str) is None:
                    # ignore an invalid q
                    continue

                q = float(q_str)
            else:
                q = 1

            if options:
                # reconstruct the value with remaining options
                item = dump_options_header(item, options)

            result.append((item, q))

        return cls(result)

    def to_header(self) -> str:
        """Convert to a header value."""
        result = []

        for value, q in self:
            if q != 1:
                value = f"{value};q={q}"

            result.append(value)

        return ",".join(result)

    def __str__(self) -> str:
        return self.to_header()

    def _best_single_match(self, app_value: str) -> tuple[str, float] | None:
        for req_value, q in self:
            if self._value_matches(app_value, req_value):
                return req_value, q

        return None

    @t.overload
    def best_match(self, within: cabc.Iterable[str]) -> str | None: ...
    @t.overload
    def best_match(self, within: cabc.Iterable[str], default: str) -> str: ...
    def best_match(
        self, within: cabc.Iterable[str], default: str | None = None
    ) -> str | None:
        """The best value within a list of potential values based on quality
        and specificity. If multiple values have the same score, the first is
        returned.

        :param within: The potential values to pick from.
        :param default: The value to return if there is no match.
        """
        result = default
        best_quality: float = -1
        best_specificity: tuple[float, ...] = (-1,)

        for app_value in within:
            if (match := self._best_single_match(app_value)) is None:
                continue

            req_value, q = match
            specificity = self._specificity(req_value)

            if q <= 0 or q < best_quality:
                continue

            # better quality or same quality but more specific => better match
            if q > best_quality or specificity > best_specificity:
                result = app_value
                best_quality = q
                best_specificity = specificity

        return result

    @property
    def best(self) -> str | None:
        """The best value based on quality and specificity. ``None`` if the
        collection is empty.
        """
        if self:
            return self[0][0]

        return None

class Response(BaseResponse):
    """
    Encapsulates a WSGI response.  Unlike the default response object werkzeug
    provides, this accepts a genshi stream and will automatically render it
    to html.  This makes it possible to switch to xhtml or html5 easily.
    """

    default_mimetype = "text/html"

    def __init__(
        self, response=None, status=200, headers=None, mimetype=None, content_type=None
    ):
        if isinstance(response, Stream):
            response = response.render("html", encoding=None, doctype="html")
        super().__init__(response, status, headers, mimetype, content_type)

def _plain_int(value: str, base: t.Literal[10, 16] = 10) -> int:
    """Parse an int only if it valid ASCII characters for the base.

    This disallows ``+``, ``_``, ``0x``, and non-ASCII digits, which are
    accepted by ``int`` but are not allowed in HTTP header values.

    Any surrounding spaces and tabs are stripped.
    """
    value = value.strip(" \t")

    if _plain_int_re[base].fullmatch(value) is None:
        raise ValueError(value)

    return int(value, base)

